import events from './events.json' with {type:'json'};

const DEFAULT_PAGE_SIZE = 2;
const MAX_PAGE_SIZE = 3;
const MIN_PAGE_SIZE = 1;

function encodeCursor(index) {
  return Buffer.from(`idx:${index}`).toString('base64');
}

function decodeCursor(cursor) {
  let decoded;
  try {
    decoded = Buffer.from(cursor, 'base64').toString('utf8');
  } catch {
    throw new Error('Invalid cursor');
  }
  const match = /^idx:(\d+)$/.exec(decoded);
  if (!match) throw new Error('Invalid cursor');
  const index = Number(match[1]);
  if (!Number.isInteger(index) || index < 0 || index >= events.length) {
    throw new Error('Invalid cursor');
  }
  return index;
}

export async function listTools() {
  return [{
    name: 'events_list',
    description: 'List events in source order with optional pagination.',
    inputSchema: {
      type: 'object',
      properties: {
        cursor: { type: 'string' },
        page_size: { type: 'integer', minimum: 1, maximum: 3 }
      },
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args = {}) {
  if (name !== 'events_list') throw new Error('Unknown tool');
  // validate args
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const keys = Object.keys(args);
  for (const k of keys) {
    if (k !== 'cursor' && k !== 'page_size') throw new Error('Invalid arguments');
  }
  let page_size = DEFAULT_PAGE_SIZE;
  if ('page_size' in args) {
    const ps = args.page_size;
    if (!Number.isInteger(ps) || ps < MIN_PAGE_SIZE || ps > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer from 1 to 3');
    }
    page_size = ps;
  }
  let start = 0;
  if ('cursor' in args) {
    if (typeof args.cursor !== 'string') throw new Error('cursor must be a string');
    start = decodeCursor(args.cursor);
  }
  const slice = events.slice(start, start + page_size);
  const end = start + slice.length;
  const result = { events: slice };
  if (end < events.length) {
    result.next_cursor = encodeCursor(end);
  }
  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}
