+import events from './events.json' with {type: 'json'};
+
+const DEFAULT_PAGE_SIZE = 2;
+const MIN_PAGE_SIZE = 1;
+const MAX_PAGE_SIZE = 3;
+const ALLOWED_ARGS = new Set(['cursor', 'page_size']);
+
+export async function listTools() {
+  return [
+    {
+      name: 'events_list',
+      description: 'List events in source order with cursor-based pagination.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          cursor: {
+            type: 'string',
+            description: 'Opaque cursor returned from a previous page. Omit for the first page.'
+          },
+          page_size: {
+            type: 'integer',
+            minimum: MIN_PAGE_SIZE,
+            maximum: MAX_PAGE_SIZE,
+            default: DEFAULT_PAGE_SIZE,
+            description: 'Number of events per page (1 to 3, default 2).'
+          }
+        },
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+function encodeCursor(offset) {
+  return Buffer.from(JSON.stringify({ o: offset })).toString('base64url');
+}
+
+function decodeCursor(cursor) {
+  if (typeof cursor !== 'string') {
+    throw new Error('cursor must be a string');
+  }
+  let parsed;
+  try {
+    parsed = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
+  } catch {
+    throw new Error('Unknown cursor');
+  }
+  if (typeof parsed !== 'object' || parsed === null || !Number.isInteger(parsed.o)) {
+    throw new Error('Unknown cursor');
+  }
+  if (parsed.o < 0 || parsed.o >= events.length) {
+    throw new Error('Unknown cursor');
+  }
+  return parsed.o;
+}
+
+function validateArguments(args) {
+  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
+    throw new Error('arguments must be an object');
+  }
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.has(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+  let pageSize = DEFAULT_PAGE_SIZE;
+  if (args.page_size !== undefined) {
+    if (!Number.isInteger(args.page_size) ||
+        args.page_size < MIN_PAGE_SIZE ||
+        args.page_size > MAX_PAGE_SIZE) {
+      throw new Error('page_size must be an integer between 1 and 3');
+    }
+    pageSize = args.page_size;
+  }
+  let offset = 0;
+  if (args.cursor !== undefined) {
+    offset = decodeCursor(args.cursor);
+  }
+  return { offset, pageSize };
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'events_list') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  const { offset, pageSize } = validateArguments(args);
+  const slice = events.slice(offset, offset + pageSize);
+  const result = { events: slice };
+  if (offset + pageSize < events.length) {
+    result.next_cursor = encodeCursor(offset + pageSize);
+  }
+  return {
+    content: [{ type: 'text', text: JSON.stringify(result) }]
+  };
+}
